import os
import logging
import time
import datetime
from moler.util.moler_test import MolerTest
from moler.device import DeviceFactory
from moler.exceptions import ConnectionObserverTimeout
from taf.rfrl.bts.devices.generic_bts import GenericBts, login_logout
from taf.rfrl.utilities.tl_config import load_moler_configuration_from_tl
from taf.rfrl.bts.devices.du.cell_operations import GnbCellOperations
from taf.rfrl.bts.devices.du.logs_collecting.btslog_collector import GnbBtslogCollector


class MeasureSoftwareUpgrade(GenericBts):
    """Base keywords for eNB and gNB"""

    def __init__(self, bts_type='GNB'):
        """
        Constructor of GenericBbbu class.
        :param bts_type: GNB|ENB
        :return: None
        """
        super(MeasureSoftwareUpgrade, self).__init__(bts_type=bts_type)
        self.cell = GnbCellOperations()
        self.log = GnbBtslogCollector()

    def measure_du_software_upgrade_time(self, path, success_rate, average_target, timeout=2500, bts_id=0, du_id=0):
        """
        Perform DU sw upgrade, measure time and verify if meet average time target and success rate ratio.
        :param path: list of absolute paths on VM with expected DU build to update
        :param bts_id:  default BTS id
        :param du_id: default DU id
        :param success_rate: Target PASSED to RUNS ratio
        :param average_target: Target sw download time in seconds.
        :param timeout:  time in seconds to wait for sw upgrade
        """
        max_target = 1.2 * float(average_target)
        passed = 0
        failed = 0
        runs = len(path)
        passed_time_results = []

        for p in path:
            upgrade_time_result = self._measure_du_software_upgrade_time(p, timeout=int(timeout), bts_id=0,
                                                                         du_id=0)
            time.sleep(60)

            if upgrade_time_result == "FileNotFoundError":
                runs -= 1
                logging.warning("FileNotFoundError for {}. Skipping...".format(p))
            elif isinstance(upgrade_time_result, datetime.timedelta):
                if max_target < upgrade_time_result.total_seconds():
                    failed += 1
                else:
                    passed += 1
                    passed_time_results.append(upgrade_time_result.total_seconds())
            else:
                failed += 1

        exceptions = []
        if len(passed_time_results) > 0:
            average_sw_upgrade_time = sum(passed_time_results) / len(passed_time_results)
            logging.info("Average SW activation duration {}".format(average_sw_upgrade_time))

            if int(average_target) <= int(average_sw_upgrade_time):
                exceptions.append(AverageSwUpgradeDurationNotMet("Average Sw upgrade time {}s exceed presume "
                                                                 "value {}s".format(average_sw_upgrade_time,
                                                                                    average_target)))

        if runs > 0:
            passed_ratio = passed / runs
            if float(passed_ratio) < float(success_rate):
                exceptions.append(SwUpgradeDurationNotMet("Runs: {}, Failed: {}, Ratio: {} "
                                                          "Target not met".format(runs, failed, passed_ratio)))

        if exceptions:
            raise SwUpgradeDurationNotMet("\n".join([repr(e) for e in exceptions]))
        elif runs == 0 or len(passed_time_results) == 0:
            raise SwUpgradeDurationNotMet("No software upgrade was performed or no test passed. "
                                          "Runs: {}, Passed upgrades: {}".format(runs, len(passed_time_results)))
        else:
            logging.info("Runs: {}, Ratio: {}, Avg time: {} Max time: {}".format(runs, passed_ratio,
                                                                                 round(average_sw_upgrade_time, 2),
                                                                                 max(passed_time_results)))

    @load_moler_configuration_from_tl()
    @MolerTest.raise_background_exceptions(check_steps_end=True)
    @login_logout
    def _measure_du_software_upgrade_time(self, path, timeout=2500, bts_id=0, du_id=0):
        """
        Perform DU sw activation, measure time and verify if meet average time target and success rate ratio.
        :param path: list of absolute paths on VM with expected DU build to download
        :param bts_id:  default BTS id
        :param du_id: default DU id
        :param timeout:  time in seconds to wait for sw activation
        """

        if not os.path.exists(path):
            MolerTest.steps_end()
            return "FileNotFoundError"

        try:
            start_update_time = datetime.datetime.now()

            MolerTest.info("Start upgrade sw build - downloading... {}".format(start_update_time))
            self.admin.update_software(sw_package=path, should_activate=True, timeout=timeout,
                                       connection=self.rest_alias.format(bts_id, du_id))

            MolerTest.info("Download build Finish {}".format(datetime.datetime.now()))
            cell_ids = self.cell._get_all_global_cell_ids(bts_id=bts_id, du_id=du_id)
            MolerTest.info(cell_ids)

            syslog = DeviceFactory.get_device(self.syslog_alias.format(bts_id, du_id))
            syslog.goto_state('SYSLOG', keep_state=False)
            first_cell_up = syslog.get_event(event_name="cell_status_from_offline_to_online",
                                             event_params={"till_occurs_times": 1})

            MolerTest.info("FIRST_CELL_UP_RESULT_START_CHECK: {}".format(datetime.datetime.now()))
            first_cell_up_result = first_cell_up(timeout=int(timeout))
            MolerTest.info("FIRST_CELL_UP_RESULT" + "".join(map(str, first_cell_up_result)))
            end_update_time = first_cell_up_result[0]['time']
            MolerTest.steps_end()

        except ConnectionObserverTimeout as e:
            logging.warning("ConnectionObserverTimeout: {}".format(e))
            MolerTest.steps_end()
            return

        MolerTest.info("Start time: " + str(start_update_time) + "   type: " + str(type(start_update_time)))
        MolerTest.info("End time: " + str(end_update_time) + "   type: " + str(type(end_update_time)))
        sw_upgrade_duration = (end_update_time - start_update_time)
        logging.info("Duration of Software Upgrade: {}".format(sw_upgrade_duration.total_seconds()))
        return sw_upgrade_duration


class SwUpgradeDurationNotMet(Exception):
    pass


class AverageSwUpgradeDurationNotMet(SwUpgradeDurationNotMet):
    pass


class UpgradeTargetNotMet(Exception):
    pass


class AverageUpgradeTargetNotMet(Exception):
    pass
